"""Record event node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ... import hermes_folder as hermes
from ...node_base import Node, NodeContext
from ...node_category import NodeCategory
from ...node_errors import NodeError


class RecordEventNode(Node):
    """Notes what happened for Hermes to read later; sends nothing."""

    node_type: ClassVar[str] = 'record_event_node'
    display_name: ClassVar[str] = 'Record event'
    default_alias: ClassVar[str] = 'Record event'
    description: ClassVar[str] = 'Notes what happened for Hermes to read later; sends nothing'
    category: ClassVar[str] = NodeCategory.IO
    primary_family: ClassVar[str] = 'Outputs'
    tags: ClassVar[List[str]] = ['Hermes', 'log', 'event']
    icon_name: ClassVar[str] = 'notebook-pen'
    color_hint: ClassVar[str] = 'amber'
    group: ClassVar[Optional[str]] = 'Hermes'
    selector_section: ClassVar[Optional[str]] = None
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Input', 'description': 'The value {input} puts in the summary', 'data_type': 'any', 'required': False, 'sources': ['upstream', 'vault']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Event id', 'description': 'The id of the recorded event ("" when skipped or not recorded)', 'data_type': 'string', 'required': False, 'to': ['downstream', 'vault'], 'pass_through': True}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Upstream payload', 'input_vault_key': '', 'event_name': '', 'summary': '', 'keep_value': False, 'skip_repeats_minutes': 0, 'repeat_key': '', 'if_not_recorded': 'Carry on', 'transient_output': False, 'dead_drop_passthrough': True, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault'], 'tab': 'Source', 'section': 'Optional Inputs', 'description': 'The value {input} puts in the summary'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Optional Inputs', 'vault_type': 'any', 'visible_when': {'input_source': 'Vault'}}, 'event_name': {'type': 'string', 'label': 'Event name', 'placeholder': "like backup.done; blank = this node's name", 'tab': 'Parameters'}, 'summary': {'type': 'string', 'label': 'Summary', 'placeholder': 'one line; {input} = the incoming value', 'tab': 'Parameters'}, 'keep_value': {'type': 'boolean', 'label': 'Also keep the incoming value (up to 2000 characters)', 'tab': 'Parameters'}, 'skip_repeats_minutes': {'type': 'number', 'label': 'Skip repeats for (minutes)', 'minimum': 0, 'maximum': 1440, 'placeholder': '0 = never skip', 'tab': 'Parameters'}, 'repeat_key': {'type': 'string', 'label': 'Repeat key', 'placeholder': 'same run + node + branch', 'tab': 'Parameters'}, 'if_not_recorded': {'type': 'select', 'label': "If it can't be recorded", 'options': [['Carry on · the run continues', 'Carry on'], ['Stop · the node fails', 'Stop with an error']], 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {'forwarded_input_port': 'input'}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'events_unwritable', 'description': 'The Hermes folder could not be written.', 'retryable': True}]

    async def execute(self, context: NodeContext) -> None:
        # Blank Event name: the node's own name ("Note: backup done").
        name = (str(self.config.get("event_name") or "").strip()
                or str(context.node_alias or "").strip() or self.display_name)
        text = hermes.as_text(hermes.node_input(self, context))
        template = str(self.config.get("summary") or "")
        summary = template.replace("{input}", text) if template.strip() else text
        # One line, harmless to Hermes, short enough to skim in a digest.
        summary = hermes.cut(hermes.escape(" ".join(summary.split())), hermes.SUMMARY_LIMIT)
        value = hermes.cut(hermes.escape(text), hermes.VALUE_LIMIT) if self.config.get("keep_value") else None

        origin = hermes.origin_of(context)
        try:
            event_id = hermes.record_event(
                origin=origin,
                name=hermes.cut(hermes.escape(name), 80),
                summary=summary,
                value=value,
                repeat_key=str(self.config.get("repeat_key") or "").strip() or hermes.default_repeat_key(origin),
                repeat_minutes=hermes.repeat_minutes(self.config.get("skip_repeats_minutes")),
            )
        except OSError as exc:
            if self.config.get("if_not_recorded") == "Stop with an error":
                context.signal_error(NodeError(
                    "events_unwritable", f"Could not write the Hermes folder: {exc}",
                    details={"folder": str(hermes.folder())}, retryable=True,
                ))
                return
            event_id = ""
        hermes.finish(self, context, event_id, "string")
